window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-73c6c24001e65e6d"]={"versions": [{"id": "FIG-73c6c24001e65e6d", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur detaillierten Spezifikation des Teilschritts „Write CRC“ innerhalb der Schutzfunktion <code>E2E_P05Protect()</code> des AUTOSAR E2E-Profils 5 (<code>AUTOSAR_PRS_E2EProtocol</code>). Der Teilschritt gehört zum Funktionsablauf der End-to-End-Absicherung von Nutzdaten vor deren Übertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Funktion</strong>: <code>E2E_P05Protect()</code> (gekennzeichnet als aufrufende Aktivität bzw. Subroutine über ein abgerundetes Rechteck mit Rake-/Entkopplungssymbol).\n</li><li><strong>Lokale Variable</strong>: <code>CRC</code> (2 Byte groß, berechneter Prüfsummenwert).\n</li><li><strong>Zielstruktur / Puffer</strong>: Byte-Array <code>Data[]</code>, adressiert über den konfigurierbaren Basis-Offset <code>Offset</code> an den Positionen <code>Data[Offset+0]</code> und <code>Data[Offset+1]</code>.\n</li><li><strong>Aktion / Anweisung</strong>: „Copy 2-byte local variable CRC on bytes Data[Offset+0...Offset+1] using Little Endian order“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Startknoten</strong>: Eintritt in den Teilschritt „Write CRC“.\n</li><li><strong>Aktionsausführung</strong>: Der 2 Byte umfassende Prüfsummenwert der lokalen Variable <code>CRC</code> wird in Little-Endian-Byte-Reihenfolge in das Array <code>Data</code> an die Indizes <code>Offset + 0</code> (niederwertiges Byte, LSB) und <code>Offset + 1</code> (höherwertiges Byte, MSB) kopiert.\n</li><li><strong>Aktivitätsendknoten</strong>: Regulärer Abschluss der CRC-Schreibsequenz und Übergang zum nachfolgenden Schritt von <code>E2E_P05Protect()</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit</strong>: Gemäß Anforderung <code>[PRS_E2E_00407]</code> ist das gezeigte Verhalten beim Serialisieren der CRC zwingend umzusetzen.\n</li><li><strong>Byte-Reihenfolge</strong>: Explizite Festlegung auf Little-Endian-Format (<code>Data[Offset+0] = CRC &amp; 0xFF</code>, <code>Data[Offset+1] = (CRC &gt;&gt; 8) &amp; 0xFF</code>), unabhängig von der nativen Prozessor-Endianness der ausführenden ECU.\n</li><li><strong>Puffergrenzen</strong>: Der aufrufende Kontext muss sicherstellen, dass das Nutzdatenarray <code>Data</code> mindestens die Länge <code>Offset + 2</code> umfasst, um Pufferüberläufe zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f73aeabe1738c798", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur detaillierten Spezifikation des Teilschritts „Write CRC“ innerhalb der Schutzfunktion <code>E2E_P05Protect()</code> des AUTOSAR E2E-Profils 5 (<code>AUTOSAR_PRS_E2EProtocol</code>). Der Teilschritt gehört zum Funktionsablauf der End-to-End-Absicherung von Nutzdaten vor deren Übertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Funktion</strong>: <code>E2E_P05Protect()</code> (gekennzeichnet als aufrufende Aktivität bzw. Subroutine über ein abgerundetes Rechteck mit Rake-/Entkopplungssymbol).\n</li><li><strong>Lokale Variable</strong>: <code>CRC</code> (2 Byte groß, berechneter Prüfsummenwert).\n</li><li><strong>Zielstruktur / Puffer</strong>: Byte-Array <code>Data[]</code>, adressiert über den konfigurierbaren Basis-Offset <code>Offset</code> an den Positionen <code>Data[Offset+0]</code> und <code>Data[Offset+1]</code>.\n</li><li><strong>Aktion / Anweisung</strong>: „Copy 2-byte local variable CRC on bytes Data[Offset+0...Offset+1] using Little Endian order“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Startknoten</strong>: Eintritt in den Teilschritt „Write CRC“.\n</li><li><strong>Aktionsausführung</strong>: Der 2 Byte umfassende Prüfsummenwert der lokalen Variable <code>CRC</code> wird in Little-Endian-Byte-Reihenfolge in das Array <code>Data</code> an die Indizes <code>Offset + 0</code> (niederwertiges Byte, LSB) und <code>Offset + 1</code> (höherwertiges Byte, MSB) kopiert.\n</li><li><strong>Aktivitätsendknoten</strong>: Regulärer Abschluss der CRC-Schreibsequenz und Übergang zum nachfolgenden Schritt von <code>E2E_P05Protect()</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit</strong>: Gemäß Anforderung <code>[PRS_E2E_00407]</code> ist das gezeigte Verhalten beim Serialisieren der CRC zwingend umzusetzen.\n</li><li><strong>Byte-Reihenfolge</strong>: Explizite Festlegung auf Little-Endian-Format (<code>Data[Offset+0] = CRC &amp; 0xFF</code>, <code>Data[Offset+1] = (CRC &gt;&gt; 8) &amp; 0xFF</code>), unabhängig von der nativen Prozessor-Endianness der ausführenden ECU.\n</li><li><strong>Puffergrenzen</strong>: Der aufrufende Kontext muss sicherstellen, dass das Nutzdatenarray <code>Data</code> mindestens die Länge <code>Offset + 2</code> umfasst, um Pufferüberläufe zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-73c6c24001e65e6d", "to": "FIG-f73aeabe1738c798", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
